static int read_data(float *A0, int nx,int ny,int nz,FILE *fp)
{
    int s=0;
    int i, j, k;
    for(i=0;i<nz;i++)
    {
        for(j=0;j<ny;j++)
        {
            for(k=0;k<nx;k++)
            {
                fread(A0+s,sizeof(float),1,fp);
                s++;
            }
        }
    }
    return 0;
}

