    MISA_Desc_t           arrB_DirStreamDesc; // = { DIR_STREAM , VALID , ACTIVE  ,arrA_metaData};
    arrB_DirStreamDesc.type   = DIR_STREAM;
    arrB_DirStreamDesc.valid  = VALID;
    arrB_DirStreamDesc.active =  ACTIVE ;

    arrB_DirStreamDesc.descInfo.streamDesc=arrB_metaData;
    // Copy from array descriptor struct to CSRs
    unsigned long long * arrBDesc = (unsigned long long * ) &arrB_DirStreamDesc;
    printf("&h_A0[0]=%p   , h_A0    Descriptor = %#llx %llx  \n"   , &h_A0[0],*(arrADesc),*(arrADesc+1));
    printf("&h_Anext[0]=%p , h_Anext  Descriptor = %#llx %llx  \n" , &h_Anext[0],*(arrBDesc),*(arrBDesc+1));

    printf("&h_A0   [size-1] = %p    \n",&h_A0   [size-1] );
    printf("&h_Anext[size-1] = %p    \n",&h_Anext[size-1] );

    write_csr(0x800, *loopADesc    ); // LOOP A
    write_csr(0x801, *(loopADesc+1)); //

    write_csr(0x802, *arrADesc    ); // h_A0
    write_csr(0x803, *(arrADesc+1)); //

    write_csr(0x804, *arrBDesc    ); // h_Anext
    write_csr(0x805, *(arrBDesc+1)); //

	printf("Start the Stencil main loop\n");
    m5_reset_stats(0,0);                    //Actual code starts here


    memcpy(h_Anext, h_A0, sizeof(float) * size);
    int t;
    for (t = 0; t < iteration; t++) {

        printf("iter=%d\n",t);
        cpu_stencil(c0, c1, h_A0, h_Anext, nx, ny, nz);
        float *temp = h_A0;
        h_A0 = h_Anext;
        h_Anext = temp;
    }

    float *temp = h_A0;
    h_A0    = h_Anext;
    h_Anext = temp   ;

    //if (parameters->outFile) {
    //    pb_SwitchToTimer(&timers, pb_TimerID_IO);
    //    outputData(parameters->outFile, h_Anext, nx, ny, nz);
    //}
    pb_SwitchToTimer(&timers, pb_TimerID_COMPUTE);
    return 0;

    // The main function continues...
    free(h_A0);
    free(h_Anext);
    pb_SwitchToTimer(&timers, pb_TimerID_NONE);

    pb_PrintTimerSet(&timers);
    pb_FreeParameters(parameters);

    return 0;
